#ifdef TEST_FORINIT_SHADOW_DV
// A name REBOUND in a `for initial` clause, where an enclosing scope binds it
// too.  Sisal 2.0 Ch6 6.1 permits re-establishing an enclosing name inside a
// `for`; 6.1.2 makes the seed a COPY that leaves the exterior binding alone.
// The front end used to half-rebind it -- symtab repointed at the local node,
// boundary still listing it as imported, and NO MERGE pair built -- so the
// name had no carry and the loop could not accumulate.  Both shapes returned 1.
//
// `X := X` is the case that pins the fix: the rebinding writes back the
// IDENTICAL (node, port) it overwrote, so the symtab retains no evidence of it
// and NO value comparison can separate it from a capture.  Only the recorded
// `inherited` provenance can.  `A := X` is the control -- it always worked,
// because A happened to be a name the boundary in-list did not hold.
//
// Reference values are computed here, not hardcoded: the same iteration in C,
// under the for-initial history semantics (the seed is body_0, and the body
// computes the new carry before the guard is re-tested).
static void test_forinit_shadow_dv(void) {
  printf("\n=== Group: forinit_shadow_dv (a rebound name must become a carry) ===\n");
  FSH_results r = func_MAIN();

  // reference: seed, then `c := old c + 1` while i <= 2, keep the last value
  auto ref_bump = [](int seed) {
    int c = seed, i = 1;
    while (i <= 2) { i = i + 1; c = c + 1; }
    return c;
  };
  const int want_zero_seeded = ref_bump(0);  // the `let` cases seed at 0
  const int want_x_seeded    = ref_bump(5);  // the alias cases seed at x = 5

  check("`w := 0` rebinding a let-bound w accumulates",
        r.let_shadow == want_zero_seeded);
  check("fresh name `q := 0` (control) agrees", r.let_fresh == want_zero_seeded);
  check("shadowed and fresh give the SAME answer",
        r.let_shadow == r.let_fresh);

  check("`X := X` (6.1.2 copy-in, written out) accumulates",
        r.self_alias == want_x_seeded);
  check("`A := X` alias carry (control) agrees", r.alias_ctl == want_x_seeded);
  check("self-alias and fresh-name alias give the SAME answer",
        r.self_alias == r.alias_ctl);

  // Nested: the inner `initial` reuses the OUTER loop's carry name.  Reference
  // is the same nest in C, with the history rule applied at both levels (the
  // seed is body_0 and so contributes to `sum`).
  int ref_c, ref_w;
  {
    int cnt = 0, w = 0, sum_w = w;      // outer seed contributes
    while (cnt < 2) {
      int i = 1, iw = 0, sum_iw = iw;   // inner seed contributes
      while (i <= 2) { int oi = i, ow = iw; i = oi + 1; iw = ow + 1; sum_iw += iw; }
      cnt = i; w = sum_iw; sum_w += w;
    }
    ref_c = cnt; ref_w = sum_w;
  }
  check("nested, inner reuses the outer carry name: last cnt",
        r.nest_sh_c == ref_c);
  check("nested, inner reuses the outer carry name: sum w",
        r.nest_sh_w == ref_w);
  check("nested, fresh inner name (control): last cnt", r.nest_rn_c == ref_c);
  check("nested, fresh inner name (control): sum w", r.nest_rn_w == ref_w);
  check("nested shadowed and nested fresh give the SAME answer",
        r.nest_sh_c == r.nest_rn_c && r.nest_sh_w == r.nest_rn_w);

  // The TEST subgraph, not just BODY.  Every case above reads the shadowed
  // carry in the body only.  TEST is wired by the same machinery and was
  // exposed identically -- a guard reading a shadowed carry would have read the
  // SEED forever, so the loop would HANG rather than return a wrong number.
  int ref_guard;
  { int w = 0; while (w < 3) w = w + 1; ref_guard = w; }
  check("`while w < 3` where w is the shadowed carry terminates and is right",
        r.guard_shadow == ref_guard);
  check("fresh guard name (control) agrees", r.guard_fresh == ref_guard);
  check("guard shadowed and guard fresh give the SAME answer",
        r.guard_shadow == r.guard_fresh);

  // Sisal 2.0 Ch6 6.1.2: re-establishing a name inside a `for` COPIES it --
  // "the exterior name is not changed".  The let bound w := 5; the loop above
  // carried its own w from 0 to 2.  Reading w after the loop must still give 5.
  // This is the other half of the rule, and the half a fix that made the carry
  // work by writing through to the outer binding would break.
  const int ref_outer_w = 5;                       // the let's binding, untouched
  check("the enclosing w is unchanged by the loop that shadowed it",
        r.outer_w == ref_outer_w);
  check("...and is NOT the carry's final value", r.outer_w != r.let_shadow);
}
#endif
#ifdef TEST_FORINIT_MASK_DV
// `when`/`unless` on a for-initial RETURNS.  These were dropped entirely --
// masked gathers and masked reductions on a sequential loop admitted every
// element, silently, for loops that RUN.  The forall path was always right,
// which is why moldyn's Get_Neighbors (a forall) worked while the same shape
// as a for-initial did not.
//
// The seed carries the interesting case: a carry's history begins with body_0,
// so the seed must be masked too, using the mask applied to the SEED.  The
// BODY's copy computes it on the post-update value instead, so masks are
// specialised in INIT and selected by their own INIT|BODY mux.  Both zero-trip
// directions are pinned below precisely so neither can pass by accident --
// before the fix, mask-TRUE-at-seed was right only because the mask was
// ignored, and mask-FALSE-at-seed was wrong.
//
// All expectations are OSC 13.0.3's, from ~/work/oldsisal.
static void test_forinit_mask_dv(void) {
  printf("\n=== Group: forinit_mask_dv (when/unless on a sequential loop) ===\n");
  FM_results r = func_MAIN();
  auto same = [](sisal_array_t a, std::vector<int> w) {
    if ((int)a.size != (int)w.size()) return 0;
    for (int i = 0; i < (int)w.size(); i++)
      if (((int32_t*)a.data)[i] != w[i]) return 0;
    return 1;
  };
  check("forall masked gather == [3,4,5] (was already right)",
        same(r.fa, { 3, 4, 5 }));
  check("for-initial masked gather == [3,4,5]", same(r.fi, { 3, 4, 5 }));
  check("forall masked reduce == 12 (was already right)", r.ra == 12);
  check("for-initial masked reduce == 12", r.ri == 12);
  check("zero-trip, mask TRUE at the seed == [10]", same(r.zt, { 10 }));
  check("zero-trip, mask FALSE at the seed == [] (seed excluded)",
        (int)r.zf.size == 0);
  check("unmasked control still the whole history == [1,2,3,4,5]",
        same(r.un, { 1, 2, 3, 4, 5 }));
  // `unless` had NO for-initial coverage in the whole corpus -- 4 forall uses,
  // zero sequential -- which is how `when` stayed broken here unnoticed.  It
  // shares that machinery, so pin it both ways: `unless p` must equal `when ~p`.
  check("for-initial `unless` gather == [1,2]", same(r.ug, { 1, 2 }));
  check("for-initial `unless` reduction == 3", r.ur == 3);
  check("`when ~p` agrees with `unless p` (gather)", same(r.wg, { 1, 2 }));
  check("`when ~p` agrees with `unless p` (reduction)", r.wr == 3);
}
#endif
#ifdef TEST_ARRAY_EX_DV
// array_dv[real]: multi-element replace rh[1:rh[2];2:rh[3]] then `|| ph`.
// rh=[1.18,7.23,3.18,10.6] -> [7.23,3.18,3.18,10.6] ++ ph=[2.18,4.23,6.18,12.6].
static void
test_array_ex_dv (void)
{
  printf ("\n=== Group: array_ex_dv (multi-replace then catenate) ===\n");
  // The program is `rh[1: rh[2]; 2: rh[3]] || ph`.  The eight result values
  // used to be written out; the reference performs the same two replaces and
  // the concatenation, which is what makes the ORDER meaningful: both replaces
  // read the ORIGINAL rh, so this is a parallel replace, not a sequential one.
  // Done sequentially, slot 2 would pick up the new slot 1 and give 7.23 there
  // instead of 3.18 -- the reference below asserts that difference explicitly.
  const std::vector<float> rh = { 1.18f, 7.23f, 3.18f, 10.6f };
  const std::vector<float> ph = { 2.18f, 4.23f, 6.18f, 12.6f };
  std::vector<float> want = rh;
  want[0] = rh[1];              // 1: rh[2]
  want[1] = rh[2];              // 2: rh[3]  -- from the ORIGINAL rh
  want.insert (want.end (), ph.begin (), ph.end ());

  sisal_array_t r = func_MAIN ();
  bool ok = ((size_t)r.size == want.size ());
  for (size_t k = 0; ok && k < want.size (); k++)
    ok = fabsf (af (r, (int)k) - want[k]) < 1e-4f;
  check ("multi-replace then catenate matches the reference (8 elements)", ok);
  check ("the two replaces read the ORIGINAL rh -- slot 2 is rh[3], not the "
         "just-written slot 1",
         ok && fabsf (want[1] - rh[2]) < 1e-6f && fabsf (want[1] - want[0]) > 1e-6f);
  if (r.data) free (r.data);
}
#endif
#ifdef TEST_NICO_DV
// Sieve of Eratosthenes over odd integers (array_dv_fill boolean + sift +
// masked-gather convert): returns the odd primes in [3, 2N+1].  Exercises the
// boolean-fill fix.  Reference = a straight sieve over [3, 2N+1].
static void test_nico_dv() {
  printf("\n=== Group: nico_dv (odd-prime sieve; array_dv_fill bool + masked gather) ===\n");
  for (int N : {3, 5, 10, 20, 50}) {
    int hi = 2 * N + 1;
    std::vector<char> comp(hi + 1, 0);
    std::vector<int32_t> ref;
    for (int p = 2; p <= hi; p++)
      if (!comp[p]) {
        if (p >= 3) ref.push_back(p);              // odd primes only (2 excluded)
        for (int m = 2 * p; m <= hi; m += p) comp[m] = 1;
      }
    sisal_array_t r = func_MAIN(N);
    int ok = (int)r.size == (int)ref.size();
    for (size_t i = 0; ok && i < ref.size(); i++) ok = ((int32_t *)r.data)[i] == ref[i];
    char tag[48]; snprintf(tag, sizeof tag, "primes in [3,%d] (N=%d)", hi, N);
    check(tag, ok);
  }
}
#endif
